using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

namespace RogControl {
 public partial class MainWindow {
  readonly Dictionary<string,Dictionary<string,object>> firmwareCatalogs=new Dictionary<string,Dictionary<string,object>>();
  readonly Dictionary<string,string> firmwareMessages=new Dictionary<string,string>();
  void OriginalGearFirmware(StackPanel target,string kind,Dictionary<string,object> state){
   status.Text="";var snapshot=GearOnline(state)?GearMap(state,"snapshot"):null;var body=new StackPanel{Width=500,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,50,0,30)};target.Children.Add(body);var icon=OriginalFirmwareIcon();icon.HorizontalAlignment=HorizontalAlignment.Center;icon.Margin=new Thickness(0,0,0,20);body.Children.Add(icon);
   var versions=new StackPanel{Margin=new Thickness(0,0,0,28)};var device=Label("设备固件版本："+OriginalStateText(snapshot,"firmware","—"),13,muted);device.Margin=new Thickness(0,0,0,5);device.TextAlignment=TextAlignment.Center;versions.Children.Add(device);var receiver=Label("接收器固件版本："+OriginalStateText(snapshot,"dongleFirmware","—"),13,muted);receiver.Margin=new Thickness(0);receiver.TextAlignment=TextAlignment.Center;versions.Children.Add(receiver);body.Children.Add(versions);
   var warning=Paragraph("提醒：\n1. 请勿在固件更新过程中拔除设备。\n2. 请勿在固件更新过程中通过设备灯光设置或 Aura Sync 页面切换灯效，或调整灯效设置。",13,muted);warning.LineHeight=21;warning.Margin=new Thickness(12,0,12,24);body.Children.Add(warning);var check=Button(busy?"正在检查…":"检查更新",async()=>await CheckOriginalFirmware(kind));check.Width=132;check.Height=34;check.Padding=new Thickness(10,4,10,4);check.Margin=new Thickness(0);check.HorizontalAlignment=HorizontalAlignment.Center;check.IsEnabled=!busy&&!closing&&!render;check.ToolTip="只读取华硕官网版本；此版本暂不提供固件刷写。";ToolTipService.SetShowOnDisabled(check,true);body.Children.Add(check);
   Dictionary<string,object> catalog;if(firmwareCatalogs.TryGetValue(kind,out catalog)){string published=OriginalStateText(catalog,"deviceFWVersion","—"),dongle=OriginalStateText(catalog,"dongleFWVersion","—"),installed=OriginalStateText(snapshot,"firmware","");var available=Label("官网版本：设备 "+published+" · 接收器 "+dongle,13,text);available.TextWrapping=TextWrapping.Wrap;available.TextAlignment=TextAlignment.Center;available.Margin=new Thickness(0,24,0,10);available.ToolTip="获取时间（UTC）："+OriginalStateText(catalog,"fetchedAtUtc","—")+"。版本适用性需要由官方更新工具确认。";body.Children.Add(available);if(installed.Length>0&&published!="—"&&String.Equals(installed,published,StringComparison.OrdinalIgnoreCase)){var same=Label("版本相同",12,muted);same.TextAlignment=TextAlignment.Center;body.Children.Add(same);}var official=Button("打开官方 GearLink",()=>OpenOfficialUrl("https://gearlink.asus.com/"));official.HorizontalAlignment=HorizontalAlignment.Center;official.Margin=new Thickness(0,8,0,0);body.Children.Add(official);}
   string firmwareMessage;if(firmwareMessages.TryGetValue(kind,out firmwareMessage)&&firmwareMessage.StartsWith("检查失败",StringComparison.Ordinal)){var failure=Label("检查失败",12,muted);failure.TextAlignment=TextAlignment.Center;failure.Margin=new Thickness(0,18,0,0);failure.ToolTip=firmwareMessage;body.Children.Add(failure);}
  }
  Canvas OriginalFirmwareIcon(){var canvas=new Canvas{Width=180,Height=170};var gear=new Polygon{Stroke=text,StrokeThickness=2,Fill=Brush("#D0D0D0")};for(int tooth=0;tooth<12;tooth++)for(int edge=0;edge<4;edge++){double angle=(tooth*4+edge)*Math.PI/24-Math.PI/2;double radius=edge==1||edge==2?54:43;gear.Points.Add(new Point(79+Math.Cos(angle)*radius,68+Math.Sin(angle)*radius));}canvas.Children.Add(gear);var hole=new Ellipse{Width=40,Height=40,Fill=bg,Stroke=muted,StrokeThickness=2};Canvas.SetLeft(hole,59);Canvas.SetTop(hole,48);canvas.Children.Add(hole);var arrow=new Polygon{Points=new PointCollection(new[]{new Point(125,80),new Point(142,80),new Point(142,116),new Point(156,116),new Point(133,143),new Point(110,116),new Point(125,116)}),Fill=accent};canvas.Children.Add(arrow);return canvas;}
  async Task CheckOriginalFirmware(string kind){if(busy||closing||render)return;busy=true;firmwareMessages[kind]="";status.Text="正在检查更新…";ShowPage(page);try{var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","firmware"},{"kind",kind}});if(!reply.ok||reply.data==null)throw new InvalidOperationException(SdkError(reply.error));firmwareCatalogs[kind]=reply.data;Log("检查完成");}catch(Exception ex){firmwareCatalogs.Remove(kind);firmwareMessages[kind]="检查失败："+ex.Message;Log(firmwareMessages[kind]);}finally{busy=false;if(!closing)ShowPage(page);}}
 }
}
